 async result(){const table=tables[this.table]||=([]);let rows=table.filter(r=>this.filters.every(f=>f(r)));const count=rows.length;
  if(this.mode==='insert'||this.mode==='upsert'){rows=this.payload.map(p=>({id:p.id||uuid(),created_at:stamp,...p}));for(const row of rows){if(this.mode==='upsert'){const found=table.find(r=>r.id&&r.id===row.id||r.user_id&&r.user_id===row.user_id||r.playlist_id&&r.playlist_id===row.playlist_id&&r.track_id===row.track_id);if(found){Object.assign(found,row);continue}}table.push(row)}}
  else if(this.mode==='update')rows.forEach(r=>Object.assign(r,this.payload));else if(this.mode==='delete')tables[this.table]=table.filter(r=>!rows.includes(r));
  for(const s of [...this.sorts].reverse())rows.sort((a,b)=>{const x=read(a,s.k),y=read(b,s.k);return (x<y?-1:x>y?1:0)*(s.ascending?1:-1)});rows=rows.slice(this.start,this.end!==null?this.end+1:this.limitN!==null?this.start+this.limitN:undefined);
  return{data:this.head?null:this.singleResult?rows[0]||null:rows,error:null,count};
 }
